import (
	Closeable from "@std/core.ms",
	expect_contains, expect_equal, expect_fault from "@std/test/test.ms",
)

fn checked(n: Int) Int!Error:
	if n < 0: return error(Error("negative"))
	return ok(n + 1)

fn wrapped(n: Int) Int!Error:
	value := checked(n)?
	return ok(value)

fn total(positive: Bool) Int:
	var sum = 0
	var i = -2

	while i < 1000:
		if found := wrapped(i):
			if positive:
				sum += found
			else:
				sum -= found
		else:
			sum -= 1

		i += 1

	return sum

fn prefix() Int:
	var sum = 9223372036854775807
	var i = 0

	while i < 2:
		if found := wrapped(i):
			sum += found
			sum -= found

		i += 1

	return sum

fn peer() Int:
	var sum = 9223372036854775807
	var value = 0
	var i = 0

	while i < 2:
		if found := checked(value):
			sum += found
		value += 1
		i += 1

	return sum

fn hidden(n: Int) Int!Error:
	if n < 0:
		return error(
			Error(
				match present(n):
					_value:
						return ok(9223372036854775807)
					none: "negative"
			)
		)
	return ok(n + 1)

fn hidden_success() Int:
	var sum = 1
	var i = -1

	while i < 1:
		if found := hidden(i):
			sum += found
		i += 1

	return sum

type BoundedResultCleanup:
	visits: List[Int]

impl Closeable for BoundedResultCleanup:
	var fn close() Unit!:
		self.visits.append(7)

fn cleanup(visits: List[Int]) Int:
	_resource := BoundedResultCleanup(visits)
	return total(true)

fn argument(value: Int, var visits: List[Int]) Int:
	visits.append(value)
	return value

fn ordered(var visits: List[Int]) Int:
	var sum = 0
	var i = -1

	while i < 2:
		if found := wrapped(argument(i, var visits)):
			sum += found
		i += 1

	return sum

test "bounded successful Results preserve both branch budgets":
	total(true) | expect_equal(500498)?
	total(false) | expect_equal(-500502)?

test "Result payload bounds retain intermediate overflow":
	(expect_fault(fn: _ignored := prefix())?) | expect_contains("Int overflow")?
	(expect_fault(fn: _ignored := peer())?) | expect_contains("Int overflow")?

test "Result helper overflow still occurs in the original call":
	(
		(expect_fault(fn: _ignored := checked(9223372036854775807))?)
		| expect_contains("Int overflow")?
	)

test "hidden successful returns in error construction keep checks":
	(expect_fault(fn: _ignored := hidden_success())?) | expect_contains("Int overflow")?

test "Result bounds preserve argument effects and cleanup":
	var visits: List[Int] = []
	ordered(var visits) | expect_equal(3)?
	visits | expect_equal([-1, 0, 1])?
	cleanup(visits) | expect_equal(500498)?

fn present[T](value: T) T?:
	return value
